package com.galleryvote.vote;
import com.galleryvote.submission.*; import com.galleryvote.user.*; import java.time.Instant; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class VoteService {private final VoteRepository votes;private final SubmissionRepository submissions;private final UserRepository users;public VoteService(VoteRepository v,SubmissionRepository s,UserRepository u){votes=v;submissions=s;users=u;}
 @Transactional public void cast(Long userId,Long submissionId){Submission s=submissions.findById(submissionId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Submission not found"));if(s.getAuthor().getId().equals(userId))throw new ResponseStatusException(HttpStatus.CONFLICT,"You cannot vote for your own submission");if(!s.getContest().isVotingOpen(Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Voting is closed");try{votes.saveAndFlush(new Vote(users.getReferenceById(userId),s));}catch(DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Vote already recorded");}}
}
